86	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
87	
88	    /**
89	     * Serializes {@link OwnerCreatedEvent}s to the JSON carried on the {@code AUDIT} logger. A single
90	     * shared, thread-safe mapper so every structured audit event is rendered identically.
91	     */
92	    private static final ObjectMapper AUDIT_MAPPER = new ObjectMapper();
93	
94	    /**
95	     * Monotonically increasing sequence assigned to each owner create, carried as the {@code seq} of
96	     * the emitted {@link OwnerCreatedEvent} so the ordering of creates can be reconstructed from the
97	     * audit stream. Held per JVM and incremented atomically so concurrent creates receive distinct,
98	     * strictly increasing values.
99	     */
100	    private static final AtomicLong CREATE_SEQUENCE = new AtomicLong();
101	
