170	    /**
171	     * The request header carrying the caller's idempotency key. When a create is repeated with a key
172	     * already seen, the originally created owner is returned with 200 instead of a duplicate being
173	     * created (see {@link #addOwner(OwnerFieldsDto)} and {@link IdempotencyKeyStore}).
174	     */
175	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
180	        String idempotencyKey = currentIdempotencyKey();
181	        Optional<Owner> existing = idempotencyKeyStore.find(idempotencyKey)
182	            .map(this.clinicService::findOwnerById);
183	        if (existing.isPresent()) {
184	            return ownerResponse(existing.get(), HttpStatus.OK);
185	        }
186	        Owner owner = createOwner(ownerFieldsDto);
187	        idempotencyKeyStore.record(idempotencyKey, owner.getId());
188	        return ownerResponse(owner, HttpStatus.CREATED);
189	    }
190	
191	    /**
192	     * Reads the {@code Idempotency-Key} header from the current request, or {@code null} when no
193	     * request is bound or the header is absent. Held in one place so the create endpoint can decide,
194	     * from the key alone, whether a create is a first occurrence or a repeat to be served from the
195	     * originally created owner.
196	     *
197	     * @return the request's idempotency key, or {@code null} when none was supplied
198	     */
199	    private String currentIdempotencyKey() {
200	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
201	            return attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
202	        }
203	        return null;
204	    }
205	
206	    /**
207	     * Validates and normalizes the submitted owner fields, builds the owner, enforces the create-time
208	     * duplicate rules and persists it, returning the saved owner. This holds the whole "make and store
209	     * a new owner" flow in one place, separate from turning that owner into an HTTP response
210	     * ({@link #ownerResponse(Owner, HttpStatus)}), so the create endpoint reads as "create the owner,
211	     * then respond" and the persisted owner is available to callers that need it beyond the response.
212	     *
213	     * @param ownerFieldsDto the submitted owner fields, normalized in place as part of the create
214	     * @return the persisted owner, with its derived fields populated
215	     */
216	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
217	        normalizeAddress(ownerFieldsDto);
218	        rejectBlankOwnerFields(ownerFieldsDto);
219	        rejectDisposableEmailDomain(ownerFieldsDto.getEmail());
220	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
221	        rejectInvalidPostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
222	        rejectCityAtCapacity(ownerFieldsDto.getCity());
223	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
224	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
225	        rejectDailyRegistrationLimit(registrationDate);
226	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
227	        ownerFieldsDto.setTelephone(normalizedTelephone);
228	        String normalizedEmail = emailNormalizer.normalize(ownerFieldsDto.getEmail());
229	        ownerFieldsDto.setEmail(normalizedEmail);
230	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
231	        owner.setRegistrationDate(registrationDate);
232	        owner.setMemberId(memberId(owner));
233	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
234	        owner.setHouseholdId(householdId(owner));
235	        rejectDuplicateIdentity(owner);
236	        owner.setPossibleDuplicateOf(sharesHousehold ? null : possibleDuplicateOf(owner));
237	        this.clinicService.saveOwner(owner);
238	        owner.setHouseholdSize(householdSize(owner));
239	        auditOwnerCreated(owner);
240	        return owner;
241	    }
242	
243	    /**
244	     * Records the audit trail for a just-created owner: the human-readable {@code AUDIT} line and, through
245	     * {@link #emitOwnerCreatedEvent(Owner)}, the structured {@link OwnerCreatedEvent}. Holding both audit
246	     * outputs in one place - separate from the create flow that produced the owner - keeps the create
247	     * pipeline reading as "make the owner, then audit it", and gives the identifiers the audit carries a
248	     * single home.
249	     *
250	     * @param owner the persisted owner just created, with its derived fields populated
251	     */
252	    private void auditOwnerCreated(Owner owner) {
253	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
254	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel(owner));
255	        emitOwnerCreatedEvent(owner);
256	    }
257	
258	    /**
259	     * Emits the immutable structured {@link OwnerCreatedEvent} for a just-created owner as a JSON
260	     * object on the {@code AUDIT} logger, alongside the human-readable audit line. The event is
261	     * stamped with the next {@link #CREATE_SEQUENCE} value and carries the owner's current
262	     * {@linkplain #primaryIdentifier(Owner) primary identifier} and reported
263	     * {@linkplain #membershipLevel(Owner) membership level}.
264	     *
265	     * @param owner the persisted owner just created
266	     */
267	    private void emitOwnerCreatedEvent(Owner owner) {
268	        OwnerCreatedEvent event = new OwnerCreatedEvent(CREATE_SEQUENCE.incrementAndGet(),
269	            owner.getId(), primaryIdentifier(owner), membershipLevel(owner));
270	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
271	    }
272	
273	    /**
274	     * The owner's primary identifier carried by the structured {@link OwnerCreatedEvent}: the owner's
275	     * unified {@code memberId}. Held in one place so the emitted event's primary identifier has a single
276	     * source shared with the human-readable audit line.
277	     *
278	     * @param owner the owner being audited
279	     * @return the owner's primary identifier
280	     */
281	    private String primaryIdentifier(Owner owner) {
282	        return owner.getMemberId();
283	    }
284	
285	    /**
286	     * Builds the response for an owner: its derived-field DTO (see
287	     * {@link #toOwnerDtoWithDerivedFields(Owner)}) as the body and a {@code Location} header pointing at
288	     * the owner's canonical URL, returned with the given {@code status}. Assembling the response in one
289	     * place keeps "what to return for an owner" separate from the create flow that produced it, so any
290	     * path that returns an owner does so identically (differing only in the status it carries).
291	     *
292	     * @param owner the persisted owner to represent
293	     * @param status the HTTP status to return
294	     * @return the owner response with its body, {@code Location} header and status
295	     */
296	    private ResponseEntity<OwnerDto> ownerResponse(Owner owner, HttpStatus status) {
297	        OwnerDto ownerDto = toOwnerDtoWithDerivedFields(owner);
298	        HttpHeaders headers = new HttpHeaders();
299	        headers.setLocation(UriComponentsBuilder.newInstance()
300	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
301	        return new ResponseEntity<>(ownerDto, headers, status);
302	    }
