393	    /**
394	     * Loads the owner with the given id and, when it exists, produces the response through
395	     * {@code action}; when no such owner exists a {@code 404 Not Found} is returned instead. The
396	     * single-owner endpoints share this "find the owner or report 404" preamble, so the lookup and
397	     * the not-found response are written in exactly one place rather than copied into each method.
398	     *
399	     * @param ownerId the id of the owner to load
400	     * @param action builds the response for an existing owner
401	     * @param <T> the response body type
402	     * @return the result of {@code action} for an existing owner, otherwise a 404 response
403	     */
404	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> action) {
405	        Owner owner = this.clinicService.findOwnerById(ownerId);
406	        if (owner == null) {
407	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
408	        }
409	        return action.apply(owner);
410	    }
411	
412	    /**
413	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
414	     * derived from server-side state rather than stored columns (the {@code bulkSignupWarning} and
415	     * {@code capacityWarning} flags, the {@code identityKey} and the {@code possibleDuplicate} pair),
416	     * and re-applies the owner's
417	     * {@code membershipLevel} through the controller ({@link #membershipLevel(Owner)}). Both the
418	     * create endpoint and the single-owner read endpoint return their owner through this method, so
419	     * an owner is decorated identically on either path and each derived field is computed in exactly
420	     * one place.
421	     *
422	     * @param owner the persisted owner to represent
423	     * @return the owner DTO with its derived read-only fields populated
424	     */
425	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
426	        owner.setHouseholdSize(householdSize(owner));
427	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
428	        int membershipLevel = membershipLevel(owner);
429	        ownerDto.setMembershipLevel(membershipLevel);
430	        ownerDto.setOwnerSegment(ownerMapper.ownerSegment(owner, membershipLevel));
431	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
432	        ownerDto.setCapacityWarning(capacityWarning(owner.getCity()));
433	        ownerDto.setIdentityKey(identityKey(owner));
434	        Integer possibleDuplicateOf = owner.getPossibleDuplicateOf();
435	        ownerDto.setPossibleDuplicate(possibleDuplicateOf != null);
436	        ownerDto.setPossibleDuplicateOf(possibleDuplicateOf);
437	        return ownerDto;
438	    }
439	
440	    /**
441	     * The {@code membershipLevel} reported for a single owner. Starts from the owner-local derivation
442	     * in {@link OwnerMapper#membershipLevel(Owner)} (the level from the owner's own membership points),
443	     * routed through the controller so the create audit log and the single-owner response agree on one
444	     * value. Unlike the mapper - which sees only the owner - the controller can reach the rest of the
445	     * clinic, so this is the single place a reported membership level is shaped by cross-owner context.
446	     *
447	     * <p>Household ceiling: the reported level is capped at one above the current maximum
448	     * {@linkplain #householdMemberLevel(Owner) level} among the owner's <em>existing</em>
449	     * {@link #householdMembers(Owner) household members} (those sharing its {@code householdId}, other
450	     * than the owner itself). With no existing household member no cap applies and the owner-local level
451	     * is reported unchanged. The cap uses each member's own owner-local level (not their reported,
452	     * capped level), so it depends only on the members' own points and cannot recurse.
453	     *
454	     * @param owner the owner whose reported membership level is wanted
455	     * @return the owner's membership level, capped at one above its household maximum
456	     */
457	    private Integer membershipLevel(Owner owner) {
458	        int ownLevel = ownerMapper.membershipLevel(owner);
459	        java.util.OptionalInt maxHouseholdLevel = householdMembers(owner).stream()
460	            .filter(member -> !java.util.Objects.equals(member.getId(), owner.getId()))
461	            .mapToInt(this::householdMemberLevel)
462	            .max();
463	        if (maxHouseholdLevel.isEmpty()) {
464	            return ownLevel;
465	        }
466	        return Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1);
467	    }
468	
469	    /**
470	     * The owner-local membership level of a household member, used only as an input to the household
471	     * ceiling in {@link #membershipLevel(Owner)}. The member's {@link Owner#getHouseholdSize()
472	     * household size} is set from its household before the level is derived, so the member's household
473	     * factor is accounted for exactly as it is when the member is reported on its own; the level itself
474	     * comes from the owner-local {@link OwnerMapper#membershipLevel(Owner)}.
475	     *
476	     * @param member an existing member of an owner's household
477	     * @return the member's owner-local membership level
478	     */
479	    private int householdMemberLevel(Owner member) {
480	        member.setHouseholdSize(householdSize(member));
481	        return ownerMapper.membershipLevel(member);
482	    }
483	
484	    /**
485	     * Canonicalizes the submitted address in place before it is validated, stored and returned, so
486	     * every later step - the required-field check, the persisted value and the response - sees the
487	     * single normalized form produced by {@link AddressNormalizer#normalize(String)} (see that method
488	     * for the trim/collapse/upper-case/abbreviation rules). Normalizing once here, at the head of the
489	     * create flow, keeps address canonicalization in exactly one place rather than spread across the
490	     * steps that read the address.
491	     *
492	     * <p>An address may be supplied either as the structured {@code addressLine1} (with an optional
493	     * {@code addressLine2}) or as the single flat {@code address}, the latter kept for backward
494	     * compatibility. Whichever address fields are supplied are normalized, and the structured fields
495	     * are preferred when present: the flat {@code address} returned is composed as the normalized
496	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
497	     * {@code addressLine2} is present; only when no {@code addressLine1} is supplied does the flat
498	     * {@code address} retain its own normalized value.
499	     *
500	     * @param ownerFieldsDto the submitted owner fields, whose address fields are replaced with their normalized form
501	     */
502	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
503	        String addressLine1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
504	        String addressLine2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
505	        String flatAddress = addressNormalizer.normalize(ownerFieldsDto.getAddress());
506	        ownerFieldsDto.setAddressLine1(addressLine1);
507	        ownerFieldsDto.setAddressLine2(addressLine2);
508	        if (addressLine1 != null && !addressLine1.isBlank()) {
509	            String composed = addressLine2 != null && !addressLine2.isBlank()
510	                ? addressLine1 + " " + addressLine2
511	                : addressLine1;
