612	    /**
613	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
614	     * the {@code memberId}.
615	     */
616	    private static final int MEMBER_ID_HASH_LENGTH = 8;
617	
618	    /**
619	     * Builds the unified {@code memberId} assigned to a newly created owner, formatted
620	     * {@code '<REGION><FY><HASH8><CHK>'}: {@code REGION} is the owner's canonical region code resolved
621	     * from its {@code postcode} (falling back to its {@code city}) through the shared
622	     * {@link Region#code(String, String)}; {@code FY} is the two-digit fiscal year of the owner's
623	     * (business-day-adjusted) {@code registrationDate} ({@link OwnerMapper#fiscalYearSegment(Owner)});
624	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the owner's
625	     * normalized telephone followed by its last name; and {@code CHK} is a single Luhn check digit over
626	     * the digits of {@code '<REGION><FY><HASH8>'} (e.g. {@code 'NSW261A2B3C4D5'}). When this base id
627	     * collides with an existing owner's {@code memberId}, {@code '-<n>'} is appended with the smallest
628	     * {@code n} of 2 or more that makes the result unique (e.g. {@code 'NSW261A2B3C4D5-2'}), so distinct
629	     * owners always receive distinct member ids.
630	     *
631	     * @param owner the owner being created, with its telephone already normalized and its registration
632	     *              date set
633	     * @return the formatted, de-duplicated member id
634	     */
635	    private String memberId(Owner owner) {
636	        String region = Region.code(owner.getPostcode(), owner.getCity());
637	        String fiscalYear = ownerMapper.fiscalYearSegment(owner);
638	        String hash8 = sha256Hasher.hexPrefix(owner.getTelephone() + owner.getLastName(), MEMBER_ID_HASH_LENGTH);
639	        String core = region + fiscalYear + hash8;
640	        String base = core + Luhn.checkDigit(core);
641	        return deduplicate(base, Owner::getMemberId);
642	    }
