644	    /**
645	     * Ensures the given {@code base} identifier does not collide with an existing owner's identifier of
646	     * the same kind, read from each owner by {@code identifier}. When no existing owner carries the base
647	     * value it is returned unchanged; otherwise {@code '-<n>'} is appended with the smallest {@code n} of
648	     * 2 or more that yields a value held by no existing owner. Owners for which {@code identifier} yields
649	     * {@code null} are ignored (a {@code null} never collides). Written field-agnostically - like the
650	     * create endpoint's other owner scans ({@link #findExistingOwner(Function, String)},
651	     * {@link #countOwners(Predicate)}) - so the collision search lives in exactly one place and each
652	     * caller supplies only which identifier it de-duplicates.
653	     *
654	     * @param base the computed base identifier to make unique among existing owners
655	     * @param identifier reads the identifier of the same kind from an existing owner (may return {@code null})
656	     * @return the base value, or a {@code '<base>-<n>'} variant that is unique among existing owners
657	     */
658	    private String deduplicate(String base, Function<Owner, String> identifier) {
659	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
660	            .map(identifier)
661	            .filter(java.util.Objects::nonNull)
662	            .collect(java.util.stream.Collectors.toSet());
663	        if (!existing.contains(base)) {
664	            return base;
665	        }
666	        int n = 2;
667	        while (existing.contains(base + "-" + n)) {
668	            n++;
669	        }
670	        return base + "-" + n;
671	    }
