812	     * @return the same date when it is a non-holiday weekday, otherwise the next business day
813	     */
814	    private LocalDate businessDay(LocalDate date) {
815	        while (isNonBusinessDay(date)) {
816	            date = date.plusDays(1);
817	        }
818	        return date;
