943	    /**
944	     * Reduces an owner to its derived {@code identityKey}: the full lower-case SHA-256 hex digest (see
945	     * {@link Sha256Hasher#hex(String)}) over {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'} -
946	     * the owner's telephone reduced to its canonical E.164 form (see
947	     * {@link TelephoneNormalizer#canonicalize(String)}), the owner's normalized (lower-cased) email or
948	     * the empty string when absent (see {@link EmailNormalizer#normalize(String)}), and the
949	     * {@linkplain Soundex#encode(String) Soundex code} of the owner's last name, joined by {@code '|'}.
950	     * Two owners are duplicates exactly when their whole identity keys are equal. The hashed input never
951	     * contains {@code null} segments, so the create endpoint's single duplicate check compares this one
952	     * value across owners.
953	     *
954	     * @param owner the owner to derive the identity key for
955	     * @return the owner's identity key, a 64-character lower-case hex string
956	     */
957	    private String identityKey(Owner owner) {
958	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
959	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
960	        String email = normalizedEmail == null ? "" : normalizedEmail;
961	        String lastNameSoundex = soundex.encode(owner.getLastName());
962	        return sha256Hasher.hex(telephone + "|" + email + "|" + lastNameSoundex);
963	    }
