967	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null} are
968	     * ignored (a {@code null} key never equals the sought key). The create endpoint's duplicate
969	     * checks reduce both an existing owner and the owner being created to the same canonical key;
970	     * this returns the matched existing owner itself, so a caller can either reject the collision or
971	     * record which owner was matched. Owners flagged deleted (soft-deleted) are excluded, so a
972	     * collision with only a deleted owner is not reported and the create is allowed.
973	     *
974	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
975	     * @param key the canonical key of the owner being created
976	     * @return the first existing owner sharing the key, or empty when none does
977	     */
978	    private Optional<Owner> findExistingOwner(Function<Owner, String> keyExtractor, String key) {
979	        return this.clinicService.findAllOwners().stream()
980	            .filter(owner -> !owner.isDeleted())
981	            .filter(owner -> key.equals(keyExtractor.apply(owner)))
982	            .findFirst();
983	    }
984	
985	    /**
986	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
987	     * from each owner by {@code keyExtractor} (see {@link #findExistingOwner(Function, String)}).
988	     * The create endpoint's duplicate checks use this to reduce both an existing owner and the owner
989	     * being created to the same canonical key and reject a match.
990	     *
991	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
992	     * @param key the canonical key of the owner being created
993	     * @return {@code true} if some existing owner shares the key
994	     */
995	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
996	        return findExistingOwner(keyExtractor, key).isPresent();
997	    }
998	
999	    /**
1000	     * Counts the existing owners that satisfy the given {@code predicate}. The create endpoint's
1001	     * count-based rules - the per-city capacity, the per-day create limit and the derived
1002	     * {@code namesakeCount} - all accumulate owners over {@link ClinicService#findAllOwners()} and
1003	     * differ only in the predicate they count by, so the scan-and-count is written in exactly one
1004	     * place and each rule supplies just its own predicate.
1005	     *
1006	     * @param predicate the condition an owner must satisfy to be counted
1007	     * @return the number of existing owners that satisfy the predicate
1008	     */
1009	    private long countOwners(Predicate<Owner> predicate) {
1010	        return this.clinicService.findAllOwners().stream()
1011	            .filter(predicate)
1012	            .count();
1013	    }
1014	
1015	    /**
1016	     * Delimiter joining the canonical {@code lastName} and the {@code postcode} when deriving the
1017	     * shared {@code householdId}.
1018	     */
1019	    private static final String HOUSEHOLD_KEY_DELIMITER = "|";
1020	
1021	    /**
1022	     * Reduces the household {@code lastName} to a canonical form for case-insensitive,
1023	     * whitespace-insensitive comparison: leading and trailing whitespace is trimmed, every run of
1024	     * internal whitespace is collapsed to a single space, and the result is lower-cased using
1025	     * {@link java.util.Locale#ROOT} so comparison is locale-independent.
1026	     *
1027	     * @param value the raw field value, or {@code null}
1028	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
1029	     */
1030	    private String canonicalizeHousehold(String value) {
1031	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
1032	    }
1033	
1034	    /**
1035	     * Derives the deterministic, shared {@code householdId} for an owner from its {@code lastName}
1036	     * and {@code postcode}. The identifier is the first 12 upper-case hex characters of the SHA-256
1037	     * hash of {@code normalizedLastName + '|' + postcode} (see {@link #canonicalizeHousehold(String)}
1038	     * for the last-name normalization), so every owner with the same last name and postcode -
1039	     * regardless of casing or spacing - is automatically assigned the identical value. Owners without
1040	     * a postcode have no household basis and are given no household id ({@code null}).
1041	     *
1042	     * @param owner the owner being created
1043	     * @return the shared household identifier, or {@code null} when the owner has no postcode
1044	     */
1045	    /**
1046	     * Counts the owners in the given owner's household: the existing owners that share its
1047	     * {@code householdId} (see {@link #householdId(Owner)}), which - because the owner being counted is
1048	     * itself persisted before it is decorated - includes the owner. An owner with no {@code householdId}
1049	     * (e.g. no postcode) has no shared household and counts as a household of one. The value feeds the
1050	     * household factor of the owner's membership points.
1051	     *
1052	     * @param owner the owner whose household size is being derived
1053	     * @return the number of owners in the owner's household (at least {@code 1})
1054	     */
1055	    private int householdSize(Owner owner) {
1056	        if (owner.getHouseholdId() == null) {
1057	            return 1;
1058	        }
1059	        return householdMembers(owner).size();
1060	    }
1061	
1062	    /**
1063	     * The existing owners that make up the given owner's household: those sharing its
1064	     * {@code householdId} (see {@link #householdId(Owner)}). An owner with no {@code householdId}
1065	     * (e.g. no postcode) belongs to no shared household, so the result is empty. Whether the owner
1066	     * itself appears depends on when the scan runs relative to the create's save: a scan taken after
1067	     * the owner is persisted (as the {@link #householdSize(Owner) household size} derivation is)
1068	     * counts it among its household, while one taken before the save sees only the owners already
1069	     * present. Holding the household lookup in one place lets every household-derived value read the
1070	     * same set of members.
1071	     *
1072	     * @param owner the owner whose household members are wanted
1073	     * @return the owners sharing the owner's household, or an empty list when it has no household
1074	     */
1075	    private List<Owner> householdMembers(Owner owner) {
1076	        String household = owner.getHouseholdId();
1077	        if (household == null) {
1078	            return List.of();
1079	        }
1080	        return this.clinicService.findAllOwners().stream()
1081	            .filter(existing -> household.equals(existing.getHouseholdId()))
1082	            .toList();
1083	    }
1084	
1085	    private String householdId(Owner owner) {
1086	        String postcode = owner.getPostcode();
1087	        if (postcode == null || postcode.isBlank()) {
1088	            return null;
1089	        }
1090	        String key = canonicalizeHousehold(owner.getLastName()) + HOUSEHOLD_KEY_DELIMITER + postcode;
1091	        return sha256Hasher.hexPrefix(key, HOUSEHOLD_ID_LENGTH);
1092	    }
1093	
1094	    /**
1095	     * Number of leading hex characters of the household hash retained as the shared
1096	     * {@code householdId}.
1097	     */
1098	    private static final int HOUSEHOLD_ID_LENGTH = 12;
1099	}
